-- =====================================================================
-- Schema for the Real-Time Customer Heart Beat Monitoring System
-- =====================================================================
-- This file runs automatically when the PostgreSQL container is created
-- for the first time (it is mounted into /docker-entrypoint-initdb.d).
-- It is safe to run again: IF NOT EXISTS skips anything already created.
-- =====================================================================

CREATE TABLE IF NOT EXISTS heartbeat_readings (
    -- Unique ID for each row, generated by PostgreSQL
    id            BIGSERIAL    PRIMARY KEY,

    -- Which customer the reading belongs to, e.g. 'CUST_001'
    customer_id   VARCHAR(20)  NOT NULL,

    -- When the heart rate was measured (the "timestamp" field in each Kafka message)
    recorded_at   TIMESTAMPTZ  NOT NULL,

    -- Beats per minute. The CHECK is a last safety net against impossible values;
    -- the consumer does the main validation before inserting.
    heart_rate    INTEGER      NOT NULL CHECK (heart_rate > 0 AND heart_rate < 300),

    -- TRUE when the reading is valid but outside the normal range (too high or too low)
    is_anomaly    BOOLEAN      NOT NULL DEFAULT FALSE,

    -- When the row was written to the database (filled in automatically)
    ingested_at   TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

-- Speeds up queries that filter or sort by time,
-- e.g. "all readings from the last 10 minutes"
CREATE INDEX IF NOT EXISTS idx_heartbeat_recorded_at
    ON heartbeat_readings (recorded_at);

-- Speeds up queries for one customer over time,
-- e.g. "customer CUST_003's readings from today"
CREATE INDEX IF NOT EXISTS idx_heartbeat_customer_time
    ON heartbeat_readings (customer_id, recorded_at);
